#!/bin/sh
set -eu
cd "$(dirname "$0")"
. /etc/os-release
expected_version=$(cat required-image-version.txt)
[ "$ID" = nocturne ] && [ "$VERSION_ID" = "$expected_version" ] || {
  echo "This UI requires Nocturne image $expected_version. Found $ID $VERSION_ID. Nothing installed."
  exit 1
}
sha256sum -c SHA256SUMS >/dev/null
ui=/opt/nocturne/webapps/ui
test -f "$ui/index.html"
test -w "$ui"
stage=$(mktemp -d /tmp/nocturne-personal.XXXXXX)
trap 'rm -rf "$stage"' EXIT
# Package contents are generated by our build, never supplied by upstream releases.
tar -xzf ui.tar.gz -C "$stage"
(cd "$stage" && sha256sum -c personal-files.sha256 >/dev/null)
backup="/var/lib/nocturne-ui-before-personal-$(date +%Y%m%d-%H%M%S).tar.gz"
tar -czf "$backup" -C "$ui" .
echo "UI backup: $backup"
systemctl stop chromium-kiosk.service
trap 'systemctl start chromium-kiosk.service; rm -rf "$stage"' EXIT
tar -xzf ui.tar.gz -C "$ui"
(cd "$ui" && sha256sum -c personal-files.sha256 >/dev/null)
sync
if command -v curl >/dev/null 2>&1; then
  served=$(curl -fsS --max-time 10 http://127.0.0.1:8080/personal-build.txt)
else
  served=$(wget -q -T 10 -O - http://127.0.0.1:8080/personal-build.txt)
fi
[ "$served" = "$(cat "$stage/personal-build.txt")" ] || { echo 'Web server is serving a different UI. Share this output.'; exit 1; }
systemctl start chromium-kiosk.service
trap 'rm -rf "$stage"' EXIT
systemctl is-active chromium-kiosk.service
echo "Installed and verified: $served"
echo 'Keep Automatic Updates disabled. This installer does not change that setting.'
